import React,{createContext,useContext,useEffect,useRef,useState,useCallback,type FormEvent,type ReactNode} from 'react';
import {Link,NavLink,Routes,Route,useNavigationType,useLocation,useNavigate,useParams,useSearchParams} from 'react-router-dom';
import {ArrowUpRight,ArrowRight,ArrowLeft,Search,Heart,ShoppingBag,UserRound,Menu,X,Plus,Minus,Check,SlidersHorizontal,ChevronDown,Truck,PackageCheck,ShieldCheck,LoaderCircle,CheckCircle2,AlertCircle} from 'lucide-react';
import {categories,collections,money,type Bootstrap,type Product,type Variant,type CartLine,type CartItem,type User,type Order,type ShopConfig} from './shared';
type ApiError=Error & {fields?:Record<string,string>};
export async function api<T>(url:string,init:RequestInit={}):Promise<T>{const r=await fetch(url,{...init,headers:{'Content-Type':'application/json',...init.headers}});const d=await r.json() as T & {error?:string;message?:string;fields?:Record<string,string>};if(!r.ok){const e=new Error(d.error||d.message||'Не удалось выполнить запрос. Попробуйте ещё раз.') as ApiError;e.fields=d.fields;throw e}return d}
const post=<T,>(url:string,data:unknown,headers?:Record<string,string>)=>api<T>(url,{method:'POST',body:JSON.stringify(data),headers});
const safeRead=<T,>(key:string,fallback:T):T=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}};
const save=(key:string,value:unknown)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{/* Storage may be unavailable in this browser. */}};
type Store={products:Product[];config:ShopConfig;user:User|null;setUser:(u:User|null)=>void;cart:CartLine[];favorites:string[];setCart:React.Dispatch<React.SetStateAction<CartLine[]>>;toggleFavorite:(id:string)=>void;add:(v:Variant,p:Product,q:number)=>void;toast:(s:string)=>void;logout:()=>Promise<void>};
const StoreContext=createContext<Store>(null!);const useStore=()=>useContext(StoreContext);const catName=(id:string)=>categories.find(c=>c[0]===id)?.[1]||id;
function StoreProvider({bootstrap,children}:{bootstrap:Bootstrap;children:ReactNode}){
 const [user,setUser]=useState(bootstrap.user),[cart,setCart]=useState<CartLine[]>([]),[favorites,setFavorites]=useState<string[]>([]),[ready,setReady]=useState(false),[notice,setNotice]=useState('');const syncedUser=useRef<string|null|undefined>(undefined);const toast=useCallback((s:string)=>setNotice(s),[]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),5200);return()=>clearTimeout(t)},[notice]);
 useEffect(()=>{let active=true;syncedUser.current=undefined;setReady(false);const guest={cart:safeRead<CartLine[]>('ll-guest-cart',[]),favorites:safeRead<string[]>('ll-guest-favorites',[])};void(async()=>{try{if(user){const pending=safeRead<{cart:CartLine[];favorites:string[]}|null>('ll-pending-'+user.id,null);if(pending)await api('/api/state',{method:'PUT',body:JSON.stringify(pending)})}const s=user?guest.cart.length||guest.favorites.length?await post<{cart:CartLine[];favorites:string[]}>('/api/state/merge',guest):await api<{cart:CartLine[];favorites:string[]}>('/api/state'):guest;if(active){setCart(s.cart);setFavorites(s.favorites);syncedUser.current=user?.id??null;if(user){save('ll-guest-cart',[]);save('ll-guest-favorites',[])}setReady(true)}}catch(e){if(active){toast((e as Error).message);setReady(true)}}})();return()=>{active=false}},[user?.id,toast]);
 useEffect(()=>{if(!ready||syncedUser.current!==(user?.id??null))return;if(user){const pendingKey='ll-pending-'+user.id,pending={cart,favorites},payload=JSON.stringify(pending);save(pendingKey,pending);const t=setTimeout(()=>{void api('/api/state',{method:'PUT',body:payload,keepalive:true}).then(()=>{if(JSON.stringify(safeRead(pendingKey,null))===payload)save(pendingKey,null)}).catch(()=>toast('Не удалось синхронизировать список. Проверьте подключение.'))},350);return()=>clearTimeout(t)}save('ll-guest-cart',cart);save('ll-guest-favorites',favorites)},[cart,favorites,ready,user,toast]);
 const toggleFavorite=(id:string)=>setFavorites(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id]);
 const add=(v:Variant,p:Product,q:number)=>{setCart(lines=>{const current=lines.find(l=>l.variantId===v.id);const quantity=Math.min(v.stock,q+(current?.quantity||0));return current?lines.map(l=>l.variantId===v.id?{...l,quantity}:l):[...lines,{variantId:v.id,quantity,price:p.price}]});toast('Добавлено в корзину. Продолжайте свою историю.')};
 const logout=async()=>{await post('/api/auth/sign-out',{});setUser(null);setCart([]);setFavorites([])};
 return <StoreContext.Provider value={{...bootstrap,user,setUser,cart,setCart,favorites,toggleFavorite,add,toast,logout}}>{children}{notice&&<div className="toast" role="status"><CheckCircle2 size={20}/><span>{notice}</span><Link to="/cart">Корзина →</Link><button aria-label="Закрыть уведомление" onClick={()=>setNotice('')}><X size={16}/></button></div>}</StoreContext.Provider>
}
function Modal({open,onClose,title,children,className=''}:{open:boolean;onClose:()=>void;title:string;children:ReactNode;className?:string}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const el=ref.current;if(open){el?.showModal();const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=old;if(el?.open)el.close()}}else el?.close()},[open]);return <dialog ref={ref} className={'modal '+className} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal-top"><h2>{title}</h2><button className="icon-button" aria-label="Закрыть" onClick={onClose}><X/></button></div>{children}</dialog>}
function Header(){const {cart,favorites,user,config}=useStore();const [menu,setMenu]=useState(false),[search,setSearch]=useState(false),[category,setCategory]=useState(false);const location=useLocation();useEffect(()=>{setMenu(false);setSearch(false);setCategory(false)},[location.pathname,location.search]);return <><div className="announcement"><span>LEGACYLAB — CONCEPT STORE</span><span>Демонстрационный магазин · без реальных списаний</span><Link to="/info/delivery">Доставка от {money(config.freeShippingThreshold,config)} за наш счёт <ArrowUpRight size={12}/></Link></div><header className="header"><div className="header-inner"><button className="icon-button mobile-menu" aria-label="Открыть меню" onClick={()=>setMenu(true)}><Menu/></button><Link to="/" className="logo" aria-label="LegacyLab — главная">LegacyLab<span className="logo-mark">✳</span></Link><nav className="desktop-nav" aria-label="Основная навигация"><div className="nav-drop"><button onClick={()=>setCategory(!category)} aria-expanded={category}>Каталог <ChevronDown size={13}/></button>{category&&<div className="mega-menu"><p className="eyebrow">YOUR EVERYDAY ARCHIVE</p><Link to="/catalog">Весь каталог <ArrowUpRight/></Link>{categories.map(([id,name])=><Link key={id} to={'/catalog?category='+id}>{name}</Link>)}<Link to="/catalog?sale=1">Архив цен</Link></div>}</div><NavLink to="/catalog?sort=new">Новое</NavLink><NavLink to="/collections">Коллекции</NavLink><NavLink to="/info/about">Мир LegacyLab</NavLink></nav><div className="header-actions"><button className="icon-button" onClick={()=>setSearch(true)} aria-label="Поиск"><Search size={21}/></button><Link className="icon-button favorite-nav" to="/favorites" aria-label={'Избранное: '+favorites.length}><Heart size={21}/>{favorites.length>0&&<i className="dot"/>}</Link><Link className="icon-button account-nav" to="/account" aria-label={user?'Личный кабинет':'Войти'}><UserRound size={21}/></Link><Link className="bag-button" to="/cart" aria-label={'Корзина, товаров: '+cart.reduce((n,l)=>n+l.quantity,0)}><ShoppingBag size={21}/><span>{cart.reduce((n,l)=>n+l.quantity,0)}</span></Link></div></div></header><Modal open={menu} onClose={()=>setMenu(false)} title="LegacyLab" className="menu-modal"><nav className="mobile-links"><Link to="/catalog">Весь каталог <ArrowUpRight/></Link>{categories.map(([id,name])=><Link key={id} to={'/catalog?category='+id}>{name}<ArrowUpRight/></Link>)}<Link to="/catalog?sort=new">Новые поступления</Link><Link to="/collections">Коллекции</Link><Link to="/favorites">Избранное</Link><Link to="/account">Личный кабинет</Link><Link to="/info/about">О LegacyLab</Link></nav><p className="muted">Создавай своё наследие.</p></Modal><SearchDialog open={search} onClose={()=>setSearch(false)}/></>}
function SearchDialog({open,onClose}:{open:boolean;onClose:()=>void}){const {config:currencyConfig}=useStore();const [q,setQ]=useState(''),[items,setItems]=useState<Product[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');const navigate=useNavigate();useEffect(()=>{if(!q.trim()){setItems([]);return}const c=new AbortController();const t=setTimeout(()=>{setBusy(true);setError('');api<{products:Product[]}>('/api/products?q='+encodeURIComponent(q),{signal:c.signal}).then(v=>setItems(v.products.slice(0,5))).catch(e=>{if(e.name!=='AbortError')setError(e.message)}).finally(()=>{if(!c.signal.aborted)setBusy(false)})},280);return()=>{clearTimeout(t);c.abort()}},[q]);return <Modal open={open} onClose={onClose} title="Найти своё" className="search-modal"><form onSubmit={e=>{e.preventDefault();navigate('/catalog?q='+encodeURIComponent(q));onClose()}} className="search-field"><Search/><input autoFocus aria-label="Поиск по названию, категории, коллекции, артикулу" placeholder="Название, коллекция или артикул" value={q} onChange={e=>setQ(e.target.value)}/>{q&&<button type="button" aria-label="Очистить поиск" onClick={()=>setQ('')}><X size={18}/></button>}<button className="button dark" type="submit">Найти</button></form><div aria-live="polite">{busy?<p className="loading"><LoaderCircle/>Ищем подходящие вещи…</p>:error?<ErrorBox text={error}/>:q&&items.length===0?<div className="empty-small"><h3>Пока ничего не нашли</h3><p>Попробуйте другое название или выберите категорию.</p></div>:items.map(p=><Link className="search-result" key={p.id} to={'/product/'+p.slug} onClick={onClose}><img src={p.images[0]} alt="" width="64" height="80"/><span><strong>{p.name}</strong><small>{p.collection}</small></span><b>{money(p.price,currencyConfig)}</b><ArrowUpRight size={18}/></Link>)}</div>{q&&items.length>0&&<Link className="text-link" to={'/catalog?q='+encodeURIComponent(q)} onClick={onClose}>Все результаты <ArrowRight size={16}/></Link>}<div className="search-cats">{categories.map(([id,name])=><Link key={id} to={'/catalog?category='+id} onClick={onClose}>{name}<ArrowUpRight size={16}/></Link>)}</div></Modal>}
function Footer(){const {config}=useStore();return <footer><div className="footer-top"><div><Link to="/" className="logo footer-logo">LegacyLab✳</Link><p>Вещи с характером.<br/>История, которую создаёшь ты.</p><span className="footer-coordinates">INDEPENDENT THINKING. EVERYDAY WEAR.</span></div><div><h3>Магазин</h3><Link to="/catalog">Каталог</Link><Link to="/catalog?sort=new">Новые поступления</Link><Link to="/collections">Коллекции</Link><Link to="/favorites">Избранное</Link></div><div><h3>Помощь</h3><Link to="/info/delivery">Доставка и оплата</Link><Link to="/info/returns">Возврат</Link><Link to="/info/faq">Вопросы и ответы</Link><Link to="/info/contacts">Контакты</Link></div><div><h3>LegacyLab</h3><Link to="/info/about">О бренде</Link><Link to="/account">Личный кабинет</Link><Link to="/info/privacy">Конфиденциальность</Link><Link to="/info/terms">Условия демомагазина</Link>{config.contactEmail&&<a href={'mailto:'+config.contactEmail}>{config.contactEmail}</a>}</div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} LegacyLab. Создавай своё наследие.</span><span>Демонстрация · товары не отправляются · оплаты нет</span><span>RU / ₽</span></div></footer>}
function Card({product:p}:{product:Product}){const {config:currencyConfig}=useStore();const {favorites,toggleFavorite}=useStore();return <article className="product-card"><div className="product-picture"><Link to={'/product/'+p.slug}><img src={p.images[0]} alt={p.name} width="600" height="750" loading="lazy"/>{p.images[1]&&<img className="product-hover" src={p.images[1]} alt="" width="600" height="750" loading="lazy"/>}</Link><div className="card-labels">{p.oldPrice?<span className="sale-label">−{Math.round((1-p.price/p.oldPrice)*100)}%</span>:p.isNew?<span>NEW</span>:<span>LEGACYLAB</span>}</div><button className={'favorite-button '+(favorites.includes(p.id)?'selected':'')} aria-label={(favorites.includes(p.id)?'Удалить из избранного: ':'В избранное: ')+p.name} aria-pressed={favorites.includes(p.id)} onClick={()=>toggleFavorite(p.id)}><Heart size={19}/></button><Link className="card-discover" to={'/product/'+p.slug}>Рассмотреть <ArrowUpRight size={17}/></Link></div><div className="product-meta"><span>{p.collection}</span><div className="swatches">{Array.from(new Map(p.variants.map(v=>[v.color,v])).values()).map(v=><i key={v.color} title={v.color} style={{background:v.colorHex}}/>)}</div></div><Link className="product-name" to={'/product/'+p.slug}>{p.name}</Link><div className="price">{money(p.price,currencyConfig)} {p.oldPrice&&<del>{money(p.oldPrice,currencyConfig)}</del>}</div></article>}
function ProductGrid({products}:{products:Product[]}){return <div className="product-grid">{products.map(p=><Card key={p.id} product={p}/>)}</div>}
function SectionTitle({eyebrow,title,link,label='Смотреть всё'}:{eyebrow:string;title:string;link?:string;label?:string}){return <div className="section-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{link&&<Link className="text-link" to={link}>{label}<ArrowUpRight size={18}/></Link>}</div>}
function ErrorBox({text,retry}:{text:string;retry?:()=>void}){return <div className="error-box" role="alert"><AlertCircle size={19}/><div>{text}{retry&&<button className="text-link" onClick={retry}>Попробовать снова</button>}</div></div>}
function Empty({title,text,icon='bag'}:{title:string;text:string;icon?:string}){return <div className="empty-state">{icon==='heart'?<Heart size={42}/>:<ShoppingBag size={42}/>}<h2>{title}</h2><p>{text}</p><Link to="/catalog" className="button dark">Найти свою вещь <ArrowUpRight size={18}/></Link></div>}
function Breadcrumbs({items}:{items:{label:string;to?:string}[]}){return <nav className="breadcrumbs" aria-label="Хлебные крошки"><Link to="/">Главная</Link>{items.map((x,i)=><React.Fragment key={i}><span>/</span>{x.to?<Link to={x.to}>{x.label}</Link>:<span aria-current="page">{x.label}</span>}</React.Fragment>)}</nav>}

function Home(){const {products}=useStore();return <><section className="hero"><img className="hero-image" src="/images/hero.webp" alt="Коллекция LegacyLab: свободные силуэты и архитектурный характер" width="1536" height="1024" fetchPriority="high"/><div className="hero-shade"/><div className="hero-top"><span>NEW SEASON / 2026</span><span>VOL. 01 — URBAN ARCHIVE</span></div><div className="hero-content"><p className="eyebrow">НЕ СЛЕДУЙ. ОСТАВЛЯЙ СЛЕД.</p><h1>Создавай<br/>своё <span>наследие.</span></h1><p className="hero-description">Современная форма. Независимый характер.<br/>Вещи, которые становятся частью твоей истории.</p><Link className="button lime" to="/catalog">Исследовать коллекцию <ArrowUpRight size={19}/></Link></div><div className="hero-bottom"><span>LEGACY IS WHAT YOU MAKE.</span><Link to="/catalog?collection=Urban+Archive">Коллекция Urban Archive <ArrowRight size={17}/></Link><span>01 / 04</span></div></section><div className="brand-strip"><span>СВОБОДА БЫТЬ СОБОЙ</span><i>✳</i><span>ФОРМА ВНЕ ВРЕМЕНИ</span><i>✳</i><span>СОЗДАВАЙ СВОЁ НАСЛЕДИЕ</span><i>✳</i><span>LEGACYLAB / EST. 2026</span></div><section className="section container"><SectionTitle eyebrow="01 / THE EVERYDAY EDIT" title="Твоя форма города" link="/catalog"/><div className="category-grid">{categories.map(([id,name],i)=>{const p=products.find(p=>p.category===id);return <Link key={id} to={'/catalog?category='+id} className={'category-card category-'+i}><div><span>0{i+1}</span><ArrowUpRight/></div>{p&&<img src={p.images[0]} alt="" loading="lazy" width="600" height="640"/>}<h3>{name}</h3><small>Исследовать категорию</small></Link>})}</div></section><section className="section container"><SectionTitle eyebrow="02 / JUST LANDED" title="Новая глава гардероба" link="/catalog?sort=new" label="Все новинки"/><ProductGrid products={products.filter(p=>p.isNew).slice(0,4)}/></section><section className="editorial"><div className="editorial-picture"><img src="/images/editorial.webp" alt="Urban Archive — исследование городских форм и фактур" width="1000" height="1100" loading="lazy"/><span className="editorial-caption">LEGACYLAB EDITORIAL / VOL. 01</span></div><div className="editorial-copy"><span className="eyebrow">КОЛЛЕКЦИЯ / ОСЕНЬ 2026</span><h2>Urban<br/><em>Archive.</em></h2><p>Город меняется. Характер остаётся.</p><p className="muted">Чёткие линии, тактильные фактуры и свободные силуэты. Коллекция для тех, кто выбирает собственный маршрут.</p><Link className="button dark" to="/catalog?collection=Urban+Archive">Открыть коллекцию <ArrowUpRight size={18}/></Link><div className="editorial-note"><span>FUNCTION / FORM / FREEDOM</span><span>LL—026</span></div></div></section><section className="section container"><SectionTitle eyebrow="03 / SELECTED BY LEGACYLAB" title="В основе твоего стиля" link="/catalog?sort=recommended" label="Вся подборка"/><ProductGrid products={[...products].sort((a,b)=>a.rank-b.rank).slice(4,8)}/><p className="selection-note">Редакционная демонстрационная подборка. Выбираем по характеру, а не по счётчику продаж.</p></section><section className="philosophy container"><div><span className="eyebrow">04 / THE LEGACY MINDSET</span><div className="ll-symbol" aria-hidden="true">L<span>L</span><i>✳</i></div></div><div><h2>Стиль — это то,<br/>что остаётся <em>твоим.</em></h2><p>Legacy — индивидуальность и вещи с историей. Lab — поиск новой формы. Мы соединяем эти идеи в гардеробе для жизни: осмысленном, свободном, твоём.</p><Link to="/info/about" className="text-link">Больше о LegacyLab <ArrowUpRight size={18}/></Link></div></section><section className="service-strip container"><Link to="/info/delivery"><Truck/><div><h3>Твой маршрут</h3><p>Понятные демонстрационные тарифы доставки</p></div><ArrowUpRight size={18}/></Link><Link to="/info/returns"><PackageCheck/><div><h3>Без лишних вопросов</h3><p>Как устроен возврат и отмена в демоверсии</p></div><ArrowUpRight size={18}/></Link><Link to="/info/terms"><ShieldCheck/><div><h3>Открыто и честно</h3><p>Тестовая покупка. Без реальной оплаты.</p></div><ArrowUpRight size={18}/></Link></section></>}
function Catalog(){const {products}=useStore();const [params,setParams]=useSearchParams();const [result,setResult]=useState({products:products.slice(0,12),total:products.length,page:1,pages:Math.ceil(products.length/12)}),[loading,setLoading]=useState(false),[error,setError]=useState(''),[filters,setFilters]=useState(false),[revision,setRevision]=useState(0);const query=params.toString();useEffect(()=>{const c=new AbortController();setLoading(true);setError('');api<typeof result>('/api/products?'+query,{signal:c.signal}).then(setResult).catch(e=>{if(e.name!=='AbortError')setError(e.message)}).finally(()=>{if(!c.signal.aborted)setLoading(false)});return()=>c.abort()},[query,revision]);
 const update=(key:string,value:string)=>{const n=new URLSearchParams(params);if(value)n.set(key,value);else n.delete(key);n.delete('page');setParams(n)};
 const submitFilters=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=new FormData(e.currentTarget),n=new URLSearchParams(params);['category','subcategory','collection','size','color','min','max','inStock','sale'].forEach(k=>{const v=String(d.get(k)||'');if(v)n.set(k,v);else n.delete(k)});n.delete('page');setParams(n);setFilters(false)};
 const title=params.get('q')?'Результаты поиска':params.get('collection')||catName(params.get('category')||'')||'Каталог';
 return <div className="container page"><Breadcrumbs items={[{label:'Каталог'}]}/><div className="page-title"><span className="eyebrow">LEGACYLAB / YOUR EVERYDAY ARCHIVE</span><h1>{title}</h1><p>{params.get('q')?'По запросу «'+params.get('q')+'»':'Вещи с характером. Выбирай то, что станет частью твоей истории.'}</p></div><div className="catalog-cats"><button className={!params.get('category')?'active':''} onClick={()=>update('category','')}>Всё</button>{categories.map(([id,name])=><button className={params.get('category')===id?'active':''} key={id} onClick={()=>update('category',id)}>{name}</button>)}</div><div className="catalog-toolbar"><button className="filter-toggle" onClick={()=>setFilters(true)}><SlidersHorizontal size={18}/>Фильтры <span>{[...params.keys()].filter(k=>!['page','sort','q'].includes(k)).length||''}</span></button><span aria-live="polite">{loading?'Обновляем…':result.total+' вещей'}</span><label className="sort-label"><span className="sr-only">Сортировка</span><select value={params.get('sort')||'recommended'} onChange={e=>update('sort',e.target.value)}><option value="recommended">Выбор LegacyLab</option><option value="new">Сначала новые</option><option value="price-asc">Сначала дешевле</option><option value="price-desc">Сначала дороже</option><option value="discount">По размеру скидки</option></select></label></div>{[...params.entries()].some(([k])=>!['page','sort'].includes(k))&&<div className="filter-chips">{[...params.entries()].filter(([k])=>!['page','sort'].includes(k)).map(([k,v])=><button key={k} onClick={()=>update(k,'')}>{k==='category'?catName(v):k==='inStock'?'В наличии':k==='sale'?'Со скидкой':k==='min'?'От '+v+' ₽':k==='max'?'До '+v+' ₽':v}<X size={13}/></button>)}<button onClick={()=>setParams({})}>Сбросить всё</button></div>}{error?<ErrorBox text={error} retry={()=>setRevision(x=>x+1)}/>:loading?<div className="product-grid" aria-label="Каталог загружается">{Array.from({length:8},(_,i)=><div key={i} className="skeleton-card"><div/><span/><span/></div>)}</div>:result.products.length?<ProductGrid products={result.products}/>:<Empty title="Ничего не нашлось" text="Попробуйте убрать часть фильтров или выберите другую категорию."/>}{result.pages>1&&<nav className="pagination" aria-label="Страницы каталога">{Array.from({length:result.pages},(_,i)=><button key={i} className={result.page===i+1?'active':''} aria-current={result.page===i+1?'page':undefined} onClick={()=>{const n=new URLSearchParams(params);n.set('page',String(i+1));setParams(n);window.scrollTo({top:200,behavior:'smooth'})}}>{i+1}</button>)}</nav>}<Modal open={filters} onClose={()=>setFilters(false)} title="Настроить выбор" className="filter-modal"><form key={query} className="stack-form" onSubmit={submitFilters}><label>Категория<select name="category" defaultValue={params.get('category')||''}><option value="">Все категории</option>{categories.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><label>Тип вещи<select name="subcategory" defaultValue={params.get('subcategory')||''}><option value="">Все типы</option>{[...new Set(products.map(p=>p.subcategory))].map(s=><option key={s}>{s}</option>)}</select></label><label>Коллекция<select name="collection" defaultValue={params.get('collection')||''}><option value="">Все коллекции</option>{collections.map(s=><option key={s}>{s}</option>)}</select></label><div className="form-row"><label>Размер<select name="size" defaultValue={params.get('size')||''}><option value="">Любой</option>{[...new Set(products.flatMap(p=>p.variants.map(v=>v.size)))].map(s=><option key={s}>{s}</option>)}</select></label><label>Цвет<select name="color" defaultValue={params.get('color')||''}><option value="">Любой</option>{[...new Set(products.flatMap(p=>p.variants.map(v=>v.color)))].map(s=><option key={s}>{s}</option>)}</select></label></div><div className="form-row"><label>Цена от, ₽<input name="min" type="number" min="0" defaultValue={params.get('min')||''} placeholder="0"/></label><label>Цена до, ₽<input name="max" type="number" min="0" defaultValue={params.get('max')||''} placeholder="30 000"/></label></div><label className="checkbox"><input type="checkbox" name="inStock" value="1" defaultChecked={params.get('inStock')==='1'}/>Только в наличии</label><label className="checkbox"><input type="checkbox" name="sale" value="1" defaultChecked={params.get('sale')==='1'}/>Со скидкой</label><button className="button dark" type="submit">Применить фильтры <ArrowRight size={16}/></button><button className="button subtle" type="button" onClick={()=>{setParams({});setFilters(false)}}>Сбросить все</button></form></Modal></div>}
function ProductPage(){const {config:currencyConfig}=useStore();const {slug}=useParams();const {products,add,favorites,toggleFavorite}=useStore();const [product,setProduct]=useState(products.find(p=>p.slug===slug)),[error,setError]=useState(''),[color,setColor]=useState(''),[size,setSize]=useState(''),[quantity,setQuantity]=useState(1),[selectionError,setSelectionError]=useState(''),[sizeGuide,setSizeGuide]=useState(false),[zoom,setZoom]=useState<string|null>(null),[recent,setRecent]=useState<string[]>([]);const sizeRef=useRef<HTMLFieldSetElement>(null);
 useEffect(()=>{const found=products.find(p=>p.slug===slug);setProduct(found);setColor(found?.variants[0]?.color||'');setSize('');setQuantity(1);setError('');setSelectionError('');const c=new AbortController();api<{product:Product}>('/api/products/'+slug,{signal:c.signal}).then(({product:p})=>{setProduct(p);setColor(p.variants[0]?.color||'');const old=safeRead<string[]>('ll-recent',[]).filter(x=>x!==p.id);setRecent(old);save('ll-recent',[p.id,...old].slice(0,10))}).catch(e=>{if(e.name!=='AbortError')setError(e.message)});return()=>c.abort()},[slug,products]);
 if(error&&!product)return <div className="container page"><ErrorBox text={error}/><Link to="/catalog" className="button dark">В каталог</Link></div>;if(!product)return <div className="container page loading"><LoaderCircle/>Загружаем вещь…</div>;
 const p=product,colors=Array.from(new Map(p.variants.map(v=>[v.color,v])).values()),variants=p.variants.filter(v=>v.color===color),variant=variants.find(v=>v.size===size);const submit=()=>{if(!variant){setSelectionError('Выберите размер, чтобы добавить вещь в корзину.');sizeRef.current?.focus();return}if(!variant.stock){setSelectionError('Этот вариант закончился. Выберите другой размер или цвет.');return}add(variant,p,quantity);setSelectionError('')};
 return <div className="container product-page"><Breadcrumbs items={[{label:'Каталог',to:'/catalog'},{label:catName(p.category),to:'/catalog?category='+p.category},{label:p.name}]}/><div className="product-layout"><div className="gallery">{p.images.map((src,i)=><button key={src+i} className="gallery-image" onClick={()=>setZoom(src)} aria-label={'Увеличить изображение '+(i+1)}><img src={src} alt={p.name+', ракурс '+(i+1)} width="800" height="1000" loading={i?'lazy':'eager'}/><span><Plus size={18}/></span></button>)}</div><div className="product-detail"><span className="eyebrow">{p.collection} / {p.isNew?'NEW ARRIVAL':'LEGACYLAB'}</span><h1>{p.name}</h1><p className="product-sku">АРТИКУЛ {p.sku}</p><div className="product-price">{money(p.price,currencyConfig)} {p.oldPrice&&<del>{money(p.oldPrice,currencyConfig)}</del>}</div><p className="product-intro">{p.description}</p><fieldset className="variant-field"><legend>Цвет <span>{color}</span></legend><div className="color-options">{colors.map(v=><button key={v.color} type="button" className={color===v.color?'selected':''} aria-label={v.color} aria-pressed={color===v.color} onClick={()=>{setColor(v.color);setSize('');setQuantity(1)}} style={{background:v.colorHex}}>{color===v.color&&<Check size={18} style={{color:'#888'}}/>}</button>)}</div></fieldset><fieldset className="variant-field" ref={sizeRef} tabIndex={-1}><legend>Размер <button onClick={()=>setSizeGuide(true)}>Таблица размеров <ArrowUpRight size={12}/></button></legend><div className="size-options">{variants.map(v=><button key={v.id} className={(size===v.size?'selected ':'')+(!v.stock?'unavailable':'')} disabled={!v.stock} aria-pressed={size===v.size} title={v.stock?v.size+' — в наличии':v.size+' — нет в наличии'} onClick={()=>{setSize(v.size);setQuantity(1);setSelectionError('')}}>{v.size}</button>)}</div></fieldset>{selectionError&&<ErrorBox text={selectionError}/>}<div className="stock-message">{variant?variant.stock>0?<><i/>В наличии · {variant.stock} шт.</>:'Нет в наличии':'Выберите свой размер — мы не выбираем за вас'}</div><div className="product-buy"><div className="quantity"><button aria-label="Уменьшить количество" disabled={quantity<=1} onClick={()=>setQuantity(x=>Math.max(1,x-1))}><Minus size={15}/></button><span>{quantity}</span><button aria-label="Увеличить количество" disabled={!variant||quantity>=variant.stock} onClick={()=>setQuantity(x=>Math.min(variant?.stock||1,x+1))}><Plus size={15}/></button></div><button className="button dark add-to-cart" onClick={submit}>В корзину <ShoppingBag size={18}/></button><button className={'icon-button favorite-detail '+(favorites.includes(p.id)?'selected':'')} aria-label="В избранное" aria-pressed={favorites.includes(p.id)} onClick={()=>toggleFavorite(p.id)}><Heart/></button></div><p className="demo-note">Демонстрационный товар. Реальной оплаты и отправки нет.</p><div className="product-perks"><Truck size={19}/><Link to="/info/delivery">Доставка от {money(currencyConfig.shipping[0]?.price??0,currencyConfig)} · бесплатно от {money(currencyConfig.freeShippingThreshold,currencyConfig)}</Link></div><div className="detail-accordions"><details open><summary>Детали и посадка <Plus size={15}/></summary><p>{p.fit}</p></details><details><summary>Состав и уход <Plus size={15}/></summary><p>{p.composition}</p><p>{p.care}</p></details><details><summary>Доставка и возврат <Plus size={15}/></summary><p>Демонстрационная доставка — 3–7 дней, экспресс — 1–3 дня. Все тарифы видны до подтверждения заказа.</p><Link to="/info/returns">Об условиях возврата →</Link></details></div></div></div><section className="section"><SectionTitle eyebrow="KEEP EXPLORING" title="В одном ритме"/><ProductGrid products={products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4)}/></section>{recent.length>0&&<section className="section"><SectionTitle eyebrow="YOUR RECENT ARCHIVE" title="Ты уже присматривался"/><ProductGrid products={recent.map(id=>products.find(x=>x.id===id)).filter((x):x is Product=>!!x).slice(0,4)}/></section>}<Modal open={sizeGuide} onClose={()=>setSizeGuide(false)} title="Найди свою посадку"><p>Демонстрационные ориентиры для свободной посадки. Измеряйте похожую вещь из своего гардероба.</p><table className="size-table"><thead><tr><th>Размер</th><th>Грудь, см</th><th>Длина, см</th></tr></thead><tbody>{[['XS','88–94','66'],['S','94–100','68'],['M','100–106','70'],['L','106–112','72'],['XL','112–118','74']].map(r=><tr key={r[0]}>{r.map(c=><td key={c}>{c}</td>)}</tr>)}</tbody></table><p className="muted">Кроссовки: 36 → 23 см, 37 → 23,5 см, 38 → 24 см, 39 → 24,5 см, 40 → 25,5 см, 41 → 26 см, 42 → 26,5 см, 43 → 27,5 см, 44 → 28 см, 45 → 29 см. OS — единый размер.</p></Modal><Modal open={!!zoom} onClose={()=>setZoom(null)} title={p.name} className="zoom-modal">{zoom&&<img src={zoom} alt={p.name}/>}</Modal></div>}
function Favorites(){const {favorites,products}=useStore();const selected=products.filter(p=>favorites.includes(p.id));return <div className="container page"><Breadcrumbs items={[{label:'Избранное'}]}/><div className="page-title"><span className="eyebrow">YOUR PERSONAL EDIT</span><h1>Избранное<span className="title-count">{selected.length}</span></h1><p>Вещи, к которым хочется вернуться.</p></div>{selected.length?<ProductGrid products={selected}/>:<Empty title="Здесь будет твоя подборка" text="Нажимай на сердце у понравившейся вещи. Мы сохраним её для следующей встречи." icon="heart"/>}{favorites.length>selected.length&&<p className="notice">Некоторые сохранённые товары сейчас недоступны в каталоге.</p>}</div>}

type Quote={items:CartItem[];subtotal:number;discount:number;shipping:number;total:number;promoCode?:string;warnings:string[]};
function useQuote(promoCode:string,shippingMethod:string){const {cart}=useStore();const [quote,setQuote]=useState<Quote|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(false),[revision,setRevision]=useState(0);useEffect(()=>{if(!cart.length){setQuote(null);return}const c=new AbortController();setLoading(true);setError('');setQuote(null);api<Quote>('/api/quote',{method:'POST',body:JSON.stringify({items:cart,promoCode,shippingMethod}),signal:c.signal}).then(setQuote).catch(e=>{if(e.name!=='AbortError')setError(e.message)}).finally(()=>{if(!c.signal.aborted)setLoading(false)});return()=>c.abort()},[cart,promoCode,shippingMethod,revision]);return{quote,error,loading,retry:()=>setRevision(x=>x+1)}}
function Summary({quote,loading,children}:{quote:Quote|null;loading:boolean;children?:ReactNode}){const {config:currencyConfig}=useStore();return <aside className="order-summary"><span className="eyebrow">YOUR LEGACY, IN A BAG</span><h2>Твой заказ</h2><dl><div><dt>Товары</dt><dd>{quote?money(quote.subtotal,currencyConfig):'—'}</dd></div>{!!quote?.discount&&<div className="discount-row"><dt>Скидка {quote.promoCode}</dt><dd>−{money(quote.discount,currencyConfig)}</dd></div>}<div><dt>Доставка</dt><dd>{quote?quote.shipping?money(quote.shipping,currencyConfig):'Бесплатно':'—'}</dd></div><div className="summary-total"><dt>Итого</dt><dd>{quote?money(quote.total,currencyConfig):'—'}</dd></div></dl>{loading&&<p className="muted" role="status">Пересчитываем сумму…</p>}{children}<p className="demo-note"><ShieldCheck size={16}/> Только демонстрационная оплата.<br/>Настоящие данные карты не нужны.</p></aside>}
function Cart(){const {config:currencyConfig}=useStore();const {cart,setCart,products,toggleFavorite,favorites}=useStore();const [promo,setPromo]=useState(''),[draft,setDraft]=useState('');const {quote,error,loading,retry}=useQuote(promo,'standard');useEffect(()=>{setPromo(safeRead<string>('ll-promo',''));setDraft(safeRead<string>('ll-promo',''))},[]);const lines=cart.map(l=>{const p=quote?.items.find(x=>x.variantId===l.variantId)?.product||products.find(p=>p.variants.some(v=>v.id===l.variantId));return{...l,product:p,variant:p?.variants.find(v=>v.id===l.variantId)}});const apply=(code:string)=>{setPromo(code);save('ll-promo',code)};
 return <div className="container page"><Breadcrumbs items={[{label:'Корзина'}]}/><div className="page-title"><span className="eyebrow">ALMOST YOURS</span><h1>Твоя корзина<span className="title-count">{cart.reduce((s,l)=>s+l.quantity,0)}</span></h1></div>{!cart.length?<Empty title="Начни свою историю" text="В корзине пока тихо. В каталоге есть вещи, с которых хочется начать."/>:<div className="checkout-layout"><div>{lines.map(l=><article className="cart-line" key={l.variantId}>{l.product&&l.variant?<><Link to={'/product/'+l.product.slug}><img src={l.product.images[0]} alt={l.product.name} width="130" height="160"/></Link><div className="cart-line-info"><span className="eyebrow">{l.product.collection}</span><Link to={'/product/'+l.product.slug}><h3>{l.product.name}</h3></Link><p>{l.variant.color} / {l.variant.size}</p><b>{money(l.product.price,currencyConfig)} <span className="muted">/ шт.</span></b><div className="line-actions"><button onClick={()=>{if(!favorites.includes(l.product!.id))toggleFavorite(l.product!.id);setCart(v=>v.filter(x=>x.variantId!==l.variantId))}}>В избранное</button><button onClick={()=>setCart(v=>v.filter(x=>x.variantId!==l.variantId))}>Удалить</button></div></div><div className="cart-line-end"><strong>{money(l.product.price*l.quantity,currencyConfig)}</strong><div className="quantity"><button aria-label="Уменьшить количество" disabled={l.quantity<=1} onClick={()=>setCart(v=>v.map(x=>x.variantId===l.variantId?{...x,quantity:x.quantity-1}:x))}><Minus size={14}/></button><span>{l.quantity}</span><button aria-label="Увеличить количество" disabled={l.quantity>=l.variant.stock} onClick={()=>setCart(v=>v.map(x=>x.variantId===l.variantId?{...x,quantity:x.quantity+1}:x))}><Plus size={14}/></button></div>{l.quantity>l.variant.stock&&<small className="field-error">Остаток изменился. Уменьшите количество.</small>}</div></>:<div><h3>Товар больше недоступен</h3><button className="text-link" onClick={()=>setCart(v=>v.filter(x=>x.variantId!==l.variantId))}>Удалить из корзины</button></div>}</article>)}<Link className="text-link back-shopping" to="/catalog"><ArrowLeft size={17}/>Продолжить выбор</Link><div className="promo-box"><h3>Есть промокод?</h3><form onSubmit={e=>{e.preventDefault();apply(draft.trim().toUpperCase())}}><input aria-label="Промокод" value={draft} onChange={e=>setDraft(e.target.value)} placeholder="LEGACY10"/><button className="button dark">Применить</button></form>{promo&&<button className="text-link" onClick={()=>{apply('');setDraft('')}}>Удалить {promo} <X size={13}/></button>}<p>LEGACY10 — скидка 10% на товары, включая распродажу. Не суммируется сама с собой. Доставка оплачивается отдельно. Порог бесплатной доставки считается после скидки.</p></div>{error&&<ErrorBox text={error} retry={retry}/>} {quote?.warnings.map(w=><div className="notice" key={w}>{w}</div>)}{!!quote?.warnings.length&&<button className="button dark" onClick={()=>setCart(v=>v.map(l=>({...l,price:quote.items.find(x=>x.variantId===l.variantId)?.product.price||l.price})))}>Принять актуальные цены</button>}</div><Summary quote={quote} loading={loading}><Link className={'button lime full '+(loading||!!error?'disabled':'')} to="/checkout" onClick={e=>{if(loading||error)e.preventDefault()}}>К оформлению <ArrowRight size={18}/></Link><p className="muted">Стандартная доставка. Другой способ можно выбрать на следующем шаге.</p></Summary></div>}</div>}
function Checkout(){const {config:currencyConfig}=useStore();const {cart,setCart,user,config}=useStore();const navigate=useNavigate();const [shipping,setShipping]=useState(config.shipping[0]?.id||'standard'),[promo,setPromo]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[fields,setFields]=useState<Record<string,string>>({}),[contact,setContact]=useState({name:user?.name||'',email:user?.email||'',phone:'',city:'',address:'',postalCode:'',comment:''}),[consent,setConsent]=useState(false);const {quote,error:quoteError,loading,retry}=useQuote(promo,shipping);const key=useRef('');
 useEffect(()=>{setPromo(safeRead<string>('ll-promo',''));const signature=JSON.stringify(cart),prior=safeRead<{signature:string;key:string}|null>('ll-checkout-key',null);key.current=prior?.signature===signature?prior.key:crypto.randomUUID();save('ll-checkout-key',{signature,key:key.current})},[cart]);
 const submit=async(e:FormEvent)=>{e.preventDefault();if(busy||loading||quoteError)return;setBusy(true);setError('');setFields({});try{const {order,accessToken}=await post<{order:Order;accessToken?:string}>('/api/orders',{items:cart,promoCode:promo,shippingMethod:shipping,contact,idempotencyKey:key.current});if(accessToken||order.accessToken)save('ll-order-'+order.id,accessToken||order.accessToken);save('ll-checkout-key',null);setCart([]);navigate('/order/'+order.id)}catch(e){setError((e as Error).message);setFields((e as ApiError).fields||{})}finally{setBusy(false)}};
 const input=(name:keyof typeof contact,label:string,type='text',autoComplete?:string,required=true)=><label key={name}>{label}<input name={name} type={type} autoComplete={autoComplete} required={required} value={contact[name]} aria-invalid={!!fields[name]} aria-describedby={fields[name]?'error-'+name:undefined} onChange={e=>setContact(v=>({...v,[name]:e.target.value}))}/>{fields[name]&&<span className="field-error" id={'error-'+name}>{fields[name]}</span>}</label>;
 return <div className="container page"><Breadcrumbs items={[{label:'Корзина',to:'/cart'},{label:'Оформление'}]}/><div className="page-title"><span className="eyebrow">THE NEXT CHAPTER</span><h1>Оформление заказа</h1><p>Это демонстрация. Реальные деньги не списываются, товары не отправляются.</p></div>{!cart.length?<Empty title="Сначала выбери свою вещь" text="Для оформления заказа добавь товар в корзину."/>:<form onSubmit={submit} className="checkout-layout"><div className="checkout-steps"><section className="checkout-step"><h2><span>01</span>Контактные данные</h2>{!user&&<p className="muted">Можно продолжить без регистрации. Уже с нами? <Link to="/account?next=/checkout">Войти</Link></p>}<div className="form-grid">{input('name','Имя','text','name')}{input('email','Email','email','email')}{input('phone','Телефон','tel','tel')}</div></section><section className="checkout-step"><h2><span>02</span>Доставка</h2><div className="shipping-options">{config.shipping.map(s=><label className={'shipping-option '+(shipping===s.id?'selected':'')} key={s.id}><input type="radio" name="shippingMethod" value={s.id} checked={shipping===s.id} onChange={()=>setShipping(s.id)}/><span><strong>{s.name}</strong><small>{s.days} · демоусловия</small></span><b>{money(s.price,currencyConfig)}</b></label>)}</div><div className="form-grid">{input('city','Город','text','address-level2')}{input('postalCode','Индекс','text','postal-code',shipping==='standard')}{input('address','Улица, дом, квартира','text','street-address')}<label>Комментарий к заказу<textarea name="comment" rows={3} value={contact.comment} onChange={e=>setContact(v=>({...v,comment:e.target.value}))}/></label></div></section><section className="checkout-step"><h2><span>03</span>Демонстрационная оплата</h2><p>После подтверждения выбери сценарий: успех, отклонение или отмена. Номер карты и банковские данные не требуются.</p></section><section className="checkout-step"><h2><span>04</span>Проверь свой выбор</h2>{quote?.items.map(l=><div className="review-line" key={l.variantId}><span>{l.product.name}<small>{l.variant.color} / {l.variant.size} × {l.quantity}</small></span><b>{money(l.product.price*l.quantity,currencyConfig)}</b></div>)}<label className="checkbox"><input type="checkbox" required checked={consent} onChange={e=>setConsent(e.target.checked)}/><span>Я принимаю <Link to="/info/terms" target="_blank">условия демомагазина</Link> и <Link to="/info/privacy" target="_blank">политику конфиденциальности</Link>.</span></label></section>{error&&<ErrorBox text={error}/>} {quoteError&&<ErrorBox text={quoteError} retry={retry}/>} {quote?.warnings.map(w=><div className="notice" key={w}>{w}</div>)}</div><Summary quote={quote} loading={loading}><button className="button lime full" disabled={busy||loading||!quote||!!quoteError||!consent} type="submit">{busy?'Создаём заказ…':'Подтвердить заказ'}{busy?<LoaderCircle className="spin" size={18}/>:<ArrowRight size={18}/>}</button><Link className="text-link" to="/cart">Вернуться в корзину</Link></Summary></form>}</div>}
const statusLabels:Record<string,string>={pending:'Ожидает оплаты',pending_payment:'Ожидает оплаты',awaiting_payment:'Ожидает оплаты',paid:'Оплачен',processing:'Собирается',packing:'Собирается',shipped:'Отправлен',delivered:'Доставлен',cancelled:'Отменён',expired:'Резерв истёк',success:'Успешно',succeeded:'Успешно',declined:'Отклонён',failed:'Отклонён',unpaid:'Не оплачен',refunded:'Возвращён'};
function OrderPage(){const {config:currencyConfig}=useStore();const {id}=useParams();const [order,setOrder]=useState<Order|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[scenario,setScenario]=useState('success'),[revision,setRevision]=useState(0),[copied,setCopied]=useState(false);const {user}=useStore();const headers=()=>({'X-Order-Token':safeRead<string>('ll-order-'+id,'')});useEffect(()=>{const fragment=new URLSearchParams(window.location.hash.slice(1)),token=fragment.get('access');if(token){save('ll-order-'+id,token);window.history.replaceState(null,'',window.location.pathname)}setError('');api<{order:Order}>('/api/orders/'+id,{headers:headers()}).then(v=>setOrder(v.order)).catch(e=>setError(e.message))},[id,revision]);
 const action=async(action:string,data:unknown)=>{setBusy(true);setError('');try{const v=await post<{order:Order}>('/api/orders/'+id+'/'+action,data,headers());setOrder(v.order)}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 if(!order)return <div className="container page">{error?<ErrorBox text={error} retry={()=>setRevision(x=>x+1)}/>:<p className="loading"><LoaderCircle/>Загружаем заказ…</p>}</div>;
 const payable=['pending','pending_payment','awaiting_payment'].includes(order.status);return <div className="container page order-page"><Breadcrumbs items={[{label:'Заказ '+order.number}]}/><div className="page-title"><span className="eyebrow">YOUR LEGACY / ORDER CONFIRMATION</span><h1>Заказ {order.number}</h1><p>{new Date(order.createdAt).toLocaleString('ru-RU')} · <span className="status-badge">{statusLabels[order.status]||order.status}</span></p></div>{error&&<ErrorBox text={error}/>}<div className="checkout-layout"><div>{payable&&<section className="payment-panel"><span className="eyebrow">DEMO PAYMENT</span><h2>{order.paymentStatus==='declined'||order.paymentStatus==='failed'?'Попробуем ещё раз?':'Остался один шаг'}</h2><p>Выбери исход тестовой оплаты. Реальные списания исключены.</p><label>Сценарий<select value={scenario} onChange={e=>setScenario(e.target.value)}><option value="success">Успешная оплата</option><option value="declined">Отклонённая оплата</option><option value="cancelled">Отмена оплаты</option></select></label><button className="button dark" disabled={busy} onClick={()=>void action('pay',{scenario})}>{busy?'Обрабатываем…':'Запустить демооплату'}<ArrowRight size={18}/></button><p className="muted">Повторная попытка использует этот же заказ. Резерв действует 30 минут.</p></section>}{!payable&&order.paymentStatus==='paid'&&<div className="success-box"><CheckCircle2/><div><h2>Твоя история начинается</h2><p>Демонстрационная оплата успешна. Настоящие деньги не списаны.</p></div></div>}<section className="order-details"><h2>Состав заказа</h2>{order.items.map((l,i)=><div className="review-line" key={i}><img src={l.image} alt="" width="70" height="90"/><span>{l.name}<small>{l.color} / {l.size} × {l.quantity}</small></span><b>{money(l.price*l.quantity,currencyConfig)}</b></div>)}</section><section className="order-details"><h2>Данные заказа</h2><dl className="contact-details"><div><dt>Получатель</dt><dd>{order.contact.name}</dd></div><div><dt>Email</dt><dd>{order.contact.email}</dd></div><div><dt>Телефон</dt><dd>{order.contact.phone}</dd></div><div><dt>Адрес</dt><dd>{order.contact.city}, {order.contact.address}{order.contact.postalCode?', '+order.contact.postalCode:''}</dd></div><div><dt>Доставка</dt><dd>{currencyConfig.shipping.find(s=>s.id===order.shippingMethod)?.name||order.shippingMethod} · демонстрационная</dd></div><div><dt>Платёж</dt><dd>{statusLabels[order.paymentStatus]||order.paymentStatus}</dd></div></dl>{order.contact.comment&&<p>Комментарий: {order.contact.comment}</p>}</section>{order.history.length>0&&<section className="order-details"><h2>История</h2>{order.history.map((h,i)=><p className="history-row" key={i}><span>{statusLabels[h.status]||h.status}{h.comment?' · '+h.comment:''}</span><small>{new Date(h.createdAt).toLocaleString('ru-RU')}</small></p>)}</section>}</div><aside className="order-summary"><h2>Сведения сохранены</h2><dl><div><dt>Товары</dt><dd>{money(order.subtotal,currencyConfig)}</dd></div><div><dt>Скидка</dt><dd>−{money(order.discount,currencyConfig)}</dd></div><div><dt>Доставка</dt><dd>{money(order.shipping,currencyConfig)}</dd></div><div className="summary-total"><dt>Итого</dt><dd>{money(order.total,currencyConfig)}</dd></div></dl><button className="button dark full" onClick={()=>window.print()}>Сохранить / распечатать</button><p className="muted">Письмо не отправлялось. {user?'Заказ доступен в личном кабинете.':'Доступ сохранён в этом браузере. Сохраните защищённую ссылку для другого устройства.'}</p>{!user&&<button className="button subtle full" onClick={()=>{const token=safeRead<string>('ll-order-'+id,'');const url=location.origin+'/order/'+id+'#access='+encodeURIComponent(token);void navigator.clipboard.writeText(url).then(()=>setCopied(true)).catch(()=>setError('Не удалось скопировать ссылку. Сохраните заказ через печать.'))}}>{copied?'Ссылка скопирована':'Скопировать защищённую ссылку'}</button>}{['pending','pending_payment','awaiting_payment'].includes(order.status)&&<button className="text-link" disabled={busy} onClick={()=>{if(window.confirm('Отменить демонстрационный заказ? Остатки будут возвращены.'))void action('cancel',{})}}>Отменить заказ</button>}<Link className="text-link" to="/catalog">Продолжить знакомство <ArrowRight size={16}/></Link></aside></div></div>}

type Address={id:string;name:string;city:string;address:string;postalCode:string;phone:string};
function Account(){const {config:currencyConfig}=useStore();const {user,setUser,logout,toast}=useStore();const [params]=useSearchParams();const navigate=useNavigate();const [mode,setMode]=useState(params.has('token')?'reset':'login'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[orders,setOrders]=useState<Order[]>([]),[name,setName]=useState(user?.name||''),[addresses,setAddresses]=useState<Address[]>([]),[tab,setTab]=useState('orders');
 useEffect(()=>{if(!user)return;setName(user.name);void api<{orders:Order[]}>('/api/orders').then(v=>setOrders(v.orders)).catch(e=>setError(e.message));void api<{name:string;addresses:Address[]}>('/api/profile').then(v=>{setName(v.name);setAddresses(v.addresses)}).catch(e=>setError(e.message))},[user]);
 const auth=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');setMessage('');const d=Object.fromEntries(new FormData(e.currentTarget));try{if(mode==='forgot'){await post('/api/auth/request-password-reset',{email:d.email,redirectTo:location.origin+'/account'});setMessage('Если адрес зарегистрирован, инструкция для восстановления отправлена.');}else if(mode==='reset'){await post('/api/auth/reset-password',{newPassword:d.password,token:params.get('token')});setMessage('Пароль обновлён. Можно войти.');setMode('login')}else{await post('/api/auth/'+(mode==='register'?'sign-up/email':'sign-in/email'),{name:d.name,email:d.email,password:d.password});const me=await api<{user:User}>('/api/me');setUser(me.user);const next=params.get('next');if(next?.startsWith('/')&&!next.startsWith('//'))navigate(next)}}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const profile=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await api('/api/profile',{method:'PUT',body:JSON.stringify({name,addresses})});if(user)setUser({...user,name});toast('Профиль сохранён.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 if(!user)return <div className="account-entry"><div className="account-brand"><span className="eyebrow">YOUR PERSONAL ARCHIVE</span><h1>Твоя история.<br/>Твоё пространство.</h1><p>Сохраняй любимые вещи, следи за заказами и возвращайся к своему.</p><span className="account-symbol">LL.</span></div><div className="account-form"><span className="eyebrow">LEGACYLAB ACCOUNT</span><h2>{mode==='register'?'Начнём знакомство':mode==='forgot'?'Восстановить доступ':mode==='reset'?'Новый пароль':'С возвращением'}</h2>{['login','register'].includes(mode)&&<div className="account-tabs"><button className={mode==='login'?'active':''} onClick={()=>{setMode('login');setError('')}}>Войти</button><button className={mode==='register'?'active':''} onClick={()=>{setMode('register');setError('')}}>Создать аккаунт</button></div>}<form onSubmit={auth} className="stack-form">{mode==='register'&&<label>Имя<input name="name" required autoComplete="name"/></label>}{mode!=='reset'&&<label>Email<input name="email" type="email" required autoComplete="email"/></label>}{mode!=='forgot'&&<label>Пароль<input name="password" type="password" minLength={10} required autoComplete={mode==='login'?'current-password':'new-password'}/><small>Не менее 10 символов</small></label>}{mode==='register'&&<label className="checkbox"><input type="checkbox" required/><span>Принимаю <Link to="/info/privacy">политику конфиденциальности</Link> и <Link to="/info/terms">условия демомагазина</Link>.</span></label>}{error&&<ErrorBox text={error}/>} {message&&<div className="notice" role="status">{message}</div>}<button className="button dark full" disabled={busy}>{busy?'Подождите…':mode==='register'?'Создать аккаунт':mode==='forgot'?'Получить инструкцию':mode==='reset'?'Сохранить пароль':'Войти'}<ArrowRight size={18}/></button></form><button className="text-link" onClick={()=>{setMode(mode==='forgot'?'login':'forgot');setError('');setMessage('')}}>{mode==='forgot'?'Вернуться ко входу':'Не помню пароль'}</button><p className="demo-note">Для покупки регистрация необязательна. Не используйте пароль от других сервисов.</p></div></div>;
 return <div className="container page"><Breadcrumbs items={[{label:'Личный кабинет'}]}/><div className="page-title"><span className="eyebrow">YOUR PERSONAL ARCHIVE</span><h1>Привет, {user.name}.</h1><p>{user.email}</p></div><div className="account-layout"><nav className="account-sidebar"><button className={tab==='orders'?'active':''} onClick={()=>setTab('orders')}>Мои заказы <ArrowUpRight size={16}/></button><button className={tab==='profile'?'active':''} onClick={()=>setTab('profile')}>Профиль и адреса <ArrowUpRight size={16}/></button><Link to="/favorites">Избранное <Heart size={16}/></Link>{user.role==='admin'&&<Link to="/admin">Управление магазином <ArrowUpRight size={16}/></Link>}<button onClick={()=>void logout().catch(e=>setError(e.message))}>Выйти</button></nav><div>{error&&<ErrorBox text={error}/>} {tab==='orders'?<><h2>Мои заказы</h2>{orders.length?orders.map(o=><Link className="account-order" to={'/order/'+o.id} key={o.id}><div><strong>{o.number}</strong><small>{new Date(o.createdAt).toLocaleDateString('ru-RU')}</small></div><span className="status-badge">{statusLabels[o.status]||o.status}</span><b>{money(o.total,currencyConfig)}</b><ArrowUpRight size={18}/></Link>):<Empty title="Первая глава ещё впереди" text="Здесь появятся ваши заказы, оформленные после входа в аккаунт."/>}</>:<form onSubmit={profile} className="stack-form"><h2>Личные данные</h2><label>Имя<input required value={name} onChange={e=>setName(e.target.value)} autoComplete="name"/></label><h2>Сохранённые адреса</h2>{addresses.map((a,i)=><fieldset className="address-card" key={a.id}><legend>Адрес {i+1}</legend><div className="form-grid">{(['name','city','address','postalCode','phone'] as const).map((k,j)=><label key={k}>{['Название адреса','Город','Улица, дом, квартира','Индекс','Телефон'][j]}<input required={['name','city','address'].includes(k)} value={a[k]} onChange={e=>setAddresses(v=>v.map(x=>x.id===a.id?{...x,[k]:e.target.value}:x))}/></label>)}</div><button type="button" className="text-link" onClick={()=>setAddresses(v=>v.filter(x=>x.id!==a.id))}>Удалить адрес</button></fieldset>)}{addresses.length<10&&<button type="button" className="button subtle" onClick={()=>setAddresses(v=>[...v,{id:crypto.randomUUID(),name:'',city:'',address:'',postalCode:'',phone:''}])}><Plus size={17}/>Добавить адрес</button>}<button className="button dark" disabled={busy}>Сохранить изменения <Check size={18}/></button></form>}</div></div></div>}
type Promo={code:string;percent:number;active:boolean;expiresAt:string|null;minSubtotal:number;maxUses:number|null;uses?:number};
type AdminData={products:Product[];orders:Order[];promos:Promo[];config:ShopConfig};
function Admin(){const {config:currencyConfig}=useStore();const {user,toast}=useStore();const [data,setData]=useState<AdminData|null>(null),[error,setError]=useState(''),[tab,setTab]=useState('products'),[edit,setEdit]=useState<Product|null>(null),[busy,setBusy]=useState(false),[query,setQuery]=useState(''),[status,setStatus]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[promo,setPromo]=useState<Promo>({code:'',percent:10,active:true,expiresAt:null,minSubtotal:0,maxUses:null});
 const refresh=useCallback(()=>{setError('');void api<AdminData>('/api/admin').then(setData).catch(e=>setError(e.message))},[]);useEffect(()=>{if(user?.role==='admin')refresh()},[user,refresh]);
 const mutate=async(url:string,body:unknown,method='PUT')=>{setBusy(true);setError('');try{await api(url,{method,body:JSON.stringify(body)});toast('Изменения сохранены.');refresh();return true}catch(e){setError((e as Error).message);return false}finally{setBusy(false)}};
 if(!user)return <div className="container page"><h1>Управление LegacyLab</h1><p>Для доступа войдите в аккаунт владельца.</p><Link to="/account?next=/admin" className="button dark">Войти</Link></div>;
 if(user.role!=='admin')return <div className="container page"><h1>Доступ ограничен</h1><p>Этот раздел доступен владельцу магазина. Права проверяются сервером.</p><Link to="/account" className="button dark">В личный кабинет</Link></div>;
 const newProduct=()=>{const id=crypto.randomUUID();setEdit({id,slug:'new-'+id.slice(0,8),sku:'LL-'+id.slice(0,8).toUpperCase(),name:'Новая вещь',category:'clothing',subcategory:'Футболки',collection:collections[0],description:'Описание вещи',composition:'Состав',care:'Уход',fit:'Посадка',price:490000,oldPrice:null,images:data?.products[0]?.images||['/images/hero.webp'],variants:[{id:crypto.randomUUID(),productId:id,sku:'LL-'+id.slice(0,8)+'-M',color:'Графит',colorHex:'#242624',size:'M',stock:10}],isNew:true,rank:100,status:'draft'})};
 return <div className="container page admin"><div className="page-title"><span className="eyebrow">LEGACYLAB / CONTROL ROOM</span><h1>Управление магазином</h1><p>Доступ владельца · изменения сохраняются в базе магазина.</p></div><div className="catalog-cats">{[['products','Товары'],['orders','Заказы'],['promos','Промокоды'],['settings','Настройки']].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setQuery('')}}>{label}</button>)}</div>{error&&<ErrorBox text={error} retry={refresh}/>} {!data?<p className="loading"><LoaderCircle/>Загрузка…</p>:tab==='products'?<><div className="admin-toolbar"><input aria-label="Найти товар" placeholder="Название или артикул" value={query} onChange={e=>setQuery(e.target.value)}/><button className="button dark" onClick={newProduct}><Plus size={17}/>Создать товар</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Товар</th><th>Коллекция</th><th>Цена</th><th>Остаток</th><th>Статус</th><th/></tr></thead><tbody>{data.products.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(query.toLowerCase())).map(p=><tr key={p.id}><td><img src={p.images[0]} alt="" width="44" height="55"/><span>{p.name}<small>{p.sku}</small></span></td><td>{p.collection}</td><td>{money(p.price,currencyConfig)}</td><td>{p.variants.reduce((n,v)=>n+v.stock,0)}</td><td>{p.status==='published'?'Опубликован':p.status==='draft'?'Черновик':'Архив'}</td><td><button className="text-link" onClick={()=>setEdit(p)}>Изменить</button></td></tr>)}</tbody></table></div></>:tab==='orders'?<><div className="admin-toolbar"><input aria-label="Номер заказа" placeholder="Поиск по номеру" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Статус заказа" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Все статусы</option>{['awaiting_payment','paid','processing','shipped','delivered','cancelled'].map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select><label>С<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>По<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div>{data.orders.filter(o=>o.number.toLowerCase().includes(query.toLowerCase())&&(!status||o.status===status)&&(!from||o.createdAt.slice(0,10)>=from)&&(!to||o.createdAt.slice(0,10)<=to)).map(o=><details className="admin-order" key={o.id}><summary><strong>{o.number}</strong><span>{o.contact.name}</span><b>{money(o.total,currencyConfig)}</b><span className="status-badge">{statusLabels[o.status]}</span><Plus size={17}/></summary><p>{new Date(o.createdAt).toLocaleString('ru-RU')} · {o.contact.email} · {o.contact.phone}</p><p>{o.contact.city}, {o.contact.address}</p><p>Оплата: {statusLabels[o.paymentStatus]}</p>{o.items.map((l,i)=><p key={i}>{l.name} / {l.color} / {l.size} × {l.quantity} — {money(l.price*l.quantity,currencyConfig)}</p>)}<form className="admin-toolbar" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void mutate('/api/admin/orders/'+o.id+'/status',{status:f.get('status'),comment:f.get('comment')},'POST')}}><select name="status" aria-label="Новый статус" defaultValue={o.status}>{['awaiting_payment','paid','processing','shipped','delivered','cancelled'].map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select><input name="comment" placeholder="Комментарий администратора" aria-label="Комментарий администратора"/><button className="button dark" disabled={busy}>Обновить статус</button></form>{o.history.map((h,i)=><p className="history-row" key={i}><span>{statusLabels[h.status]} {h.comment}</span><small>{new Date(h.createdAt).toLocaleString('ru-RU')}</small></p>)}</details>)}</>:tab==='promos'?<div className="admin-columns"><div><h2>Промокоды</h2>{data.promos.map(p=><button className="promo-admin-row" key={p.code} onClick={()=>setPromo(p)}><b>{p.code}</b><span>−{p.percent}%</span><span>{p.active?'Активен':'Отключён'}</span><small>Применений: {p.uses||0}</small></button>)}</div><form className="stack-form" onSubmit={e=>{e.preventDefault();void mutate('/api/admin/promos',promo)}}><h2>Создать / изменить</h2><label>Промокод<input required value={promo.code} onChange={e=>setPromo(v=>({...v,code:e.target.value.toUpperCase()}))}/></label><div className="form-row"><label>Скидка, %<input required type="number" min="1" max="90" value={promo.percent} onChange={e=>setPromo(v=>({...v,percent:Number(e.target.value)}))}/></label><label>Минимум заказа, ₽<input type="number" min="0" value={promo.minSubtotal/100} onChange={e=>setPromo(v=>({...v,minSubtotal:Math.round(Number(e.target.value)*100)}))}/></label></div><label>Лимит применений<input type="number" min="1" placeholder="Без ограничения" value={promo.maxUses||''} onChange={e=>setPromo(v=>({...v,maxUses:e.target.value?Number(e.target.value):null}))}/></label><label>Действует до<input type="datetime-local" value={promo.expiresAt?.slice(0,16)||''} onChange={e=>setPromo(v=>({...v,expiresAt:e.target.value?new Date(e.target.value).toISOString():null}))}/></label><label className="checkbox"><input type="checkbox" checked={promo.active} onChange={e=>setPromo(v=>({...v,active:e.target.checked}))}/>Активен</label><button className="button dark" disabled={busy}>Сохранить промокод</button></form></div>:<SettingsEditor value={data.config} busy={busy} onSave={v=>void mutate('/api/admin/config',v)}/>}
 <Modal open={!!edit} onClose={()=>setEdit(null)} title={edit?.name||'Товар'} className="product-editor">{edit&&<ProductEditor value={edit} busy={busy} error={error} onSave={async p=>{if(await mutate('/api/admin/products'+(data?.products.some(x=>x.id===p.id)?'/'+p.id:''),{product:p},data?.products.some(x=>x.id===p.id)?'PUT':'POST'))setEdit(null)}}/>}</Modal></div>}
function ProductEditor({value,busy,error,onSave}:{value:Product;busy:boolean;error:string;onSave:(p:Product)=>Promise<void>}){const [p,setP]=useState(value);const update=<K extends keyof Product>(key:K,value:Product[K])=>setP(p=>({...p,[key]:value}));return <form className="stack-form" onSubmit={e=>{e.preventDefault();void onSave(p)}}><div className="form-grid"><label>Название<input required value={p.name} onChange={e=>update('name',e.target.value)}/></label><label>Постоянный URL<input required pattern="[a-z0-9-]+" value={p.slug} onChange={e=>update('slug',e.target.value)}/></label><label>Артикул<input required value={p.sku} onChange={e=>update('sku',e.target.value)}/></label><label>Категория<select value={p.category} onChange={e=>update('category',e.target.value)}>{categories.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><label>Подкатегория<input required value={p.subcategory} onChange={e=>update('subcategory',e.target.value)}/></label><label>Коллекция<input required list="collections-list" value={p.collection} onChange={e=>update('collection',e.target.value)}/><datalist id="collections-list">{collections.map(x=><option key={x}>{x}</option>)}</datalist></label><label>Цена, ₽<input required type="number" min="1" step=".01" value={p.price/100} onChange={e=>update('price',Math.round(Number(e.target.value)*100))}/></label><label>Старая цена, ₽<input type="number" min="1" step=".01" value={p.oldPrice?p.oldPrice/100:''} onChange={e=>update('oldPrice',e.target.value?Math.round(Number(e.target.value)*100):null)}/></label><label>Статус<select value={p.status} onChange={e=>update('status',e.target.value as Product['status'])}><option value="draft">Черновик</option><option value="published">Опубликован</option><option value="archived">Архив</option></select></label><label>Порядок в подборке<input type="number" min="0" value={p.rank} onChange={e=>update('rank',Number(e.target.value))}/></label></div>{(['description','composition','care','fit'] as const).map((k,i)=><label key={k}>{['Описание','Состав','Уход','Посадка'][i]}<textarea required rows={3} value={p[k]} onChange={e=>update(k,e.target.value)}/></label>)}<label>Изображения — по одному адресу на строку, в порядке показа<textarea required rows={4} value={p.images.join('\n')} onChange={e=>update('images',e.target.value.split('\n'))}/><small>Локальный путь /images/… или постоянный HTTPS URL. Загрузку файла выполняет владелец через исходный проект.</small></label><label className="checkbox"><input type="checkbox" checked={p.isNew} onChange={e=>update('isNew',e.target.checked)}/>Новинка</label><h3>Варианты и остатки</h3>{p.variants.map((v,i)=><fieldset className="variant-editor" key={v.id}><legend>Вариант {i+1}</legend><div className="form-grid">{(['sku','color','colorHex','size','stock'] as const).map((k,j)=><label key={k}>{['Артикул варианта','Цвет','HEX цвета','Размер','Остаток'][j]}<input required type={k==='stock'?'number':k==='colorHex'?'color':'text'} min={k==='stock'?0:undefined} value={v[k]} onChange={e=>update('variants',p.variants.map(x=>x.id===v.id?{...x,[k]:k==='stock'?Number(e.target.value):e.target.value}:x))}/></label>)}</div><button type="button" className="text-link" disabled={p.variants.length<=1} onClick={()=>update('variants',p.variants.filter(x=>x.id!==v.id))}>Удалить вариант</button></fieldset>)}<button className="button subtle" type="button" onClick={()=>update('variants',[...p.variants,{id:crypto.randomUUID(),productId:p.id,sku:p.sku+'-'+(p.variants.length+1),color:'Графит',colorHex:'#242624',size:'M',stock:0}])}>Добавить вариант</button>{error&&<ErrorBox text={error}/>}<button className="button dark" disabled={busy}>Сохранить товар</button></form>}
function SettingsEditor({value,busy,onSave}:{value:ShopConfig;busy:boolean;onSave:(v:ShopConfig)=>void}){const [v,setV]=useState(value);return <form className="stack-form settings-form" onSubmit={e=>{e.preventDefault();onSave(v)}}><h2>Основные параметры</h2><label>Название магазина<input required value={v.name} onChange={e=>setV({...v,name:e.target.value})}/></label><label>Email поддержки<input type="email" value={v.contactEmail} onChange={e=>setV({...v,contactEmail:e.target.value})}/><small>Пустое поле скрывает внешний контакт.</small></label><label>Бесплатная доставка от, ₽<input type="number" min="0" value={v.freeShippingThreshold/100} onChange={e=>setV({...v,freeShippingThreshold:Math.round(Number(e.target.value)*100)})}/></label><p className="muted">Валюта: RUB · язык: ru-RU. Смена валюты требует пересчёта цен каталога в конфигурации проекта.</p><h2>Способы доставки</h2>{v.shipping.map((s,i)=><div className="address-card form-grid" key={s.id}><label>Название<input required value={s.name} onChange={e=>setV({...v,shipping:v.shipping.map((x,j)=>i===j?{...x,name:e.target.value}:x)})}/></label><label>Цена, ₽<input type="number" min="0" value={s.price/100} onChange={e=>setV({...v,shipping:v.shipping.map((x,j)=>i===j?{...x,price:Math.round(Number(e.target.value)*100)}:x)})}/></label><label>Срок<input required value={s.days} onChange={e=>setV({...v,shipping:v.shipping.map((x,j)=>i===j?{...x,days:e.target.value}:x)})}/></label></div>)}<button className="button dark" disabled={busy}>Сохранить настройки</button></form>}

const infoContent:Record<string,{title:string;eyebrow:string;intro:string;sections:{title:string;text:string}[]}>={
 about:{title:'Оставляй свой след.',eyebrow:'THE LEGACYLAB PHILOSOPHY',intro:'LegacyLab — исследование формы, индивидуальности и повседневной городской культуры.',sections:[{title:'Legacy / то, что остаётся',text:'Наследие начинается с личного выбора. Нам близки вещи с характером: спокойные, уверенные, без лишнего. Те, к которым возвращаешься каждый день.'},{title:'Lab / поиск продолжается',text:'Мы исследуем пропорции, фактуры и новые сочетания. Свободная посадка встречается с чёткой линией, нейтральный цвет — с неожиданной деталью. Так появляется гардероб, который даёт пространство тебе.'},{title:'О демонстрации',text:'LegacyLab — самостоятельная концепция демонстрационного магазина. Товары и коллекции придуманы для проекта. Изображения служат визуализацией идеи, физическое производство и продажи не ведутся.'}]},
 delivery:{title:'Твой маршрут.',eyebrow:'DELIVERY / PAYMENT',intro:'Все условия на этой странице демонстрационные. Магазин не подключён к реальным перевозчикам и платёжным системам.',sections:[{title:'Способы доставки',text:'Стандартная доставка: 490 ₽, ориентир 3–7 дней. Экспресс: 990 ₽, ориентир 1–3 дня. При сумме товаров от 15 000 ₽ после скидки доставка бесплатна. Актуальная стоимость показывается в корзине и при оформлении.'},{title:'Без настоящей оплаты',text:'После создания заказа выберите сценарий: успешная, отклонённая или отменённая оплата. Не вводите реквизиты карты. После отклонения можно повторить оплату того же заказа.'},{title:'Резерв',text:'Варианты резервируются на 30 минут после оформления. Неоплаченный просроченный заказ отменяется, а остатки возвращаются. Успешная демонстрационная оплата сохраняет покупку в истории.'}]},
 returns:{title:'Право передумать.',eyebrow:'RETURNS / CANCELLATIONS',intro:'Это демонстрационный магазин: реальных отправлений, списаний и денежных возвратов нет.',sections:[{title:'Как отменить заказ',text:'Откройте свой заказ и нажмите «Отменить заказ», пока действие доступно. Отмена меняет статус и возвращает зарезервированный остаток ровно один раз. Повторное нажатие не создаёт дополнительный остаток.'},{title:'Если оплата отклонена',text:'Выберите другой сценарий демонстрационной оплаты на странице заказа. Повторно оформлять тот же заказ не требуется.'},{title:'После отправки',text:'Для поздних этапов заказа действия ограничены. Это позволяет проверить жизненный цикл заказа в панели владельца. Условия реальной продажи и возврата должны быть разработаны отдельно перед коммерческим запуском.'}]},
 faq:{title:'Всё по делу.',eyebrow:'QUESTIONS / ANSWERS',intro:'Короткие ответы о том, как работает LegacyLab.',sections:[{title:'Можно ли купить без регистрации?',text:'Да. Гостю доступен весь сценарий покупки. Ссылка на заказ содержит секрет доступа; сохраните её после оформления и не передавайте посторонним.'},{title:'Где мои избранные вещи?',text:'Для гостя избранное хранится в браузере. После входа оно объединяется со списком аккаунта без дубликатов. Очистка данных браузера удаляет гостевые списки.'},{title:'Как работает LEGACY10?',text:'Промокод уменьшает стоимость товаров на 10%, включая вещи со скидкой. Доставка не участвует в скидке. Повторное применение не складывает скидки. Порог бесплатной доставки проверяется после скидки.'},{title:'Почему размер не выбран сразу?',text:'Мы просим выбрать размер самостоятельно, чтобы исключить случайную покупку неподходящего варианта. Зачёркнутый размер отсутствует в выбранном цвете.'},{title:'Как восстановить доступ?',text:'На странице входа есть ссылка «Не помню пароль». Отправка работает только после настройки почтового сервиса владельцем. Если сервис не подключён, интерфейс честно сообщит об этом.'}]},
 contacts:{title:'На связи.',eyebrow:'CONTACT / SUPPORT',intro:'Внешние каналы поддержки пока не настроены. Мы не публикуем вымышленные адреса, телефоны и социальные сети.',sections:[{title:'Самостоятельно',text:'Ответы о покупке, доставке и отмене собраны в разделе вопросов и ответов. Состав, статус и историю заказа можно посмотреть на его странице.'},{title:'Для владельца',text:'Email поддержки задаётся в настройках магазина. После сохранения он появится в подвале сайта и на этой странице. Настройка не подключает отправку писем автоматически.'}]},
 privacy:{title:'Твои данные.',eyebrow:'PRIVACY / DEMONSTRATION',intro:'Мы используем только сведения, необходимые для демонстрации магазина. Не вводите реальные платёжные данные и чувствительную информацию.',sections:[{title:'Что сохраняется',text:'Имя, email, телефон, адрес и комментарий сохраняются вместе с заказом. Для аккаунта сохраняются имя, email, защищённый хеш пароля, сессии, адреса и списки. Пароли в открытом виде не хранятся.'},{title:'Cookie и браузер',text:'Cookie сессии нужны для входа. Корзина и избранное гостя, недавно просмотренные товары и секрет доступа к гостевому заказу хранятся локально в браузере. Аналитические и рекламные трекеры не используются.'},{title:'Обработка и доступ',text:'Данные обрабатываются приложением в Cloudflare Workers и хранятся в D1. Пользователь видит свои заказы; владельцу доступны сведения для управления магазином. При включённом восстановлении пароля email передаётся настроенному почтовому сервису.'},{title:'Срок хранения и удаление',text:'Демонстрационные записи хранятся до удаления владельцем. Перед реальным запуском владелец должен определить оператора, контакты по вопросам данных, применимые правила и сроки хранения. Сейчас это описание поведения прототипа, а не заявление о коммерческой готовности.'}]},
 terms:{title:'Честная демонстрация.',eyebrow:'DEMO STORE / TERMS',intro:'LegacyLab создан для знакомства с дизайном и логикой интернет-магазина. Здесь нельзя заключить реальную покупку.',sections:[{title:'Товары и изображения',text:'Названия, цены, остатки и коллекции — демонстрационные данные. Изображения визуализируют оригинальный ассортимент LegacyLab и не являются предложениями товаров других брендов.'},{title:'Оформление и оплата',text:'Создание заказа запускает тестовый сценарий. Настоящие деньги не списываются, счета не выставляются, товары не отправляются. Банковские реквизиты не запрашиваются.'},{title:'Условия использования',text:'Используйте тестовые контактные данные, сохраняйте секретные ссылки на свои заказы и не пытайтесь получить чужие данные. Общедоступного аккаунта администратора с правом изменения магазина нет.'},{title:'Перед коммерческим запуском',text:'Потребуются сведения о продавце, юридические документы, реальные фотографии и характеристики, интеграция платежей и доставки, поддержка, политика данных и дополнительные проверки безопасности.'}]}
};
function Info({page:given}:{page?:string}){const {config:currencyConfig}=useStore();const {page:route}=useParams();const page=given||route||'about',data=infoContent[page],{config}=useStore();if(!data)return <NotFound/>;return <div className="container page info-page"><Breadcrumbs items={[{label:data.title}]}/><div className="info-layout"><aside><span className="eyebrow">LEGACYLAB / INFORMATION</span><nav>{Object.entries(infoContent).map(([id,v])=><Link key={id} className={id===page?'active':''} to={'/info/'+id}>{({about:'О бренде',delivery:'Доставка и оплата',returns:'Возврат',faq:'Вопросы и ответы',contacts:'Контакты',privacy:'Конфиденциальность',terms:'Условия демомагазина'} as Record<string,string>)[id]||v.title}<ArrowUpRight size={14}/></Link>)}</nav></aside><article><span className="eyebrow">{data.eyebrow}</span><h1>{data.title}</h1><p className="info-intro">{data.intro}</p>{data.sections.map(s=><section key={s.title}><h2>{s.title}</h2><p>{s.text}</p></section>)}{page==='contacts'&&config.contactEmail&&<a className="button dark" href={'mailto:'+config.contactEmail}>{config.contactEmail}<ArrowUpRight size={18}/></a>}{page==='delivery'&&<div className="notice">Текущие настройки: {config.shipping.map(s=>s.name+' — '+money(s.price,currencyConfig)+' / '+s.days).join('; ')}. Бесплатно от {money(config.freeShippingThreshold,currencyConfig)} после скидки.</div>}<Link className="text-link" to="/catalog">Исследовать LegacyLab <ArrowUpRight size={18}/></Link></article></div></div>}
function Collections(){const {products}=useStore();return <div className="container page"><Breadcrumbs items={[{label:'Коллекции'}]}/><div className="page-title"><span className="eyebrow">FOUR WAYS TO LEAVE A MARK</span><h1>Коллекции</h1><p>Четыре взгляда на твой повседневный гардероб.</p></div><div className="collections-grid">{collections.map((c,i)=><Link className={'collection-tile collection-'+i} to={'/catalog?collection='+encodeURIComponent(c)} key={c}><div className="collection-tile-top"><span>0{i+1} / LEGACYLAB</span><ArrowUpRight/></div><img src={products.find(p=>p.collection===c)?.images[0]} alt="" width="700" height="800" loading="lazy"/><div><h2>{c}</h2><p>{['Основа, которая остаётся твоей.','Город меняется. Характер остаётся.','Будущее начинается с новой формы.','Продуманные детали каждого дня.'][i]}</p><span className="text-link">Открыть коллекцию <ArrowRight size={16}/></span></div></Link>)}</div></div>}
function NotFound(){return <div className="container page not-found"><span className="eyebrow">404 / UNCHARTED TERRITORY</span><h1>Здесь пока<br/>нет следов.</h1><p>Эта страница не существует или была перемещена. Вернись к вещам с характером.</p><Link className="button dark" to="/catalog">Перейти в каталог <ArrowUpRight size={18}/></Link></div>}
function RouteEffects(){const location=useLocation(),type=useNavigationType();useEffect(()=>{const key=location.pathname+location.search;if(type==='POP'){const y=Number(sessionStorage.getItem('ll-scroll:'+key)||0);requestAnimationFrame(()=>window.scrollTo(0,y))}else window.scrollTo(0,0);return()=>{try{sessionStorage.setItem('ll-scroll:'+key,String(window.scrollY))}catch{/* Storage may be unavailable in this browser. */}}},[location.pathname,location.search,type]);return null}
export default function App({bootstrap}:{bootstrap:Bootstrap}){return <StoreProvider bootstrap={bootstrap}><a className="skip-link" href="#main">Перейти к содержимому</a><RouteEffects/><Header/><main id="main"><Routes><Route path="/" element={<Home/>}/><Route path="/catalog" element={<Catalog/>}/><Route path="/search" element={<Catalog/>}/><Route path="/product/:slug" element={<ProductPage/>}/><Route path="/favorites" element={<Favorites/>}/><Route path="/cart" element={<Cart/>}/><Route path="/checkout" element={<Checkout/>}/><Route path="/order/:id" element={<OrderPage/>}/><Route path="/orders/:id" element={<OrderPage/>}/><Route path="/account" element={<Account/>}/><Route path="/reset-password" element={<Account/>}/><Route path="/admin" element={<Admin/>}/><Route path="/collections" element={<Collections/>}/><Route path="/info/:page" element={<Info/>}/>{Object.keys(infoContent).map(page=><Route key={page} path={'/'+page} element={<Info page={page}/>}/>)}<Route path="*" element={<NotFound/>}/></Routes></main><Footer/></StoreProvider>}
